function S = nim_config_schema()
% nim_config_schema: Single source of truth for the HINEC configuration surface.
%
% Every configurable parameter is declared here exactly once: its canonical
% (nested) path, default, type, permitted values, legacy aliases, which
% tractography algorithms actually read it, and its one-line description.
%
% Everything else is derived from this:
%   - load_config_yaml  : defaults, validation, unknown-key rejection, migration
%   - nim_config_to_options : flattening to the option names the trackers read
%   - the config reference doc : generated, so docs cannot drift from code
%
% Entry fields:
%   path    - canonical dotted path, e.g. 'tractography.integrator.method'
%   default - default value (used when the key is absent)
%   type    - 'numeric' | 'string' | 'logical' | 'list'
%   allowed - cell array of permitted values for enums, {} otherwise
%   range   - [lo hi] inclusive bounds for numerics, [] otherwise
%   legacy  - cell array of superseded FLAT key names that map here
%   algos   - algorithms that read it: any of 'hinec','standard','mmf','stitching', or
%             'all'; 'n/a' marks preprocessing keys
%   help    - one-line description (used to generate documentation)
%
% Nesting is deliberately limited to two levels below a section
% (section.group.key). A third level is a parse error - see load_config_yaml.

% NOTE: cell-valued fields (default, allowed, legacy, algos) must be wrapped in
% braces when handed to struct(), otherwise struct() expands them into a struct
% ARRAY (or, for {}, an empty struct) instead of storing the cell as one value.
e = @(path, default, type, allowed, range, legacy, algos, help) struct( ...
    'path', path, 'default', {default}, 'type', type, 'allowed', {allowed}, ...
    'range', range, 'legacy', {legacy}, 'algos', {algos}, 'help', help);

S = [
% ---------------------------------------------------------------- preprocessing
e('preprocessing.run_denoising',        true,          'logical', {}, [],       {}, {'n/a'}, 'Run denoising before tensor fitting.')
e('preprocessing.denoise_method',       'dwidenoise',  'string',  {'dwidenoise','nlmeans','gaussian'}, [], {}, {'n/a'}, 'Denoising backend. Falls back to gaussian when MRtrix3 is absent.')
e('preprocessing.run_motion_correction',true,          'logical', {}, [],       {}, {'n/a'}, 'Run motion correction (FSL).')
e('preprocessing.run_eddy',             true,          'logical', {}, [],       {}, {'n/a'}, 'Run eddy-current correction (FSL).')
e('preprocessing.improve_mask',         true,          'logical', {}, [],       {}, {'n/a'}, 'Refine the brain mask using FA.')
e('preprocessing.mask_file',            '',            'string',  {}, [],       {}, {'n/a'}, 'Optional dataset-supplied brain or tracking mask. Empty runs the normal T1/DWI brain extraction stage.')
e('preprocessing.atlas_file',           '',            'string',  {}, [],       {}, {'n/a'}, 'Optional external 3-D integer label atlas (.nii/.nii.gz), already aligned to the DWI grid. Overrides atlas_type and bypasses built-in atlas registration. Background is 0; no automatic resampling or registration.')
e('preprocessing.atlas_labels_file',    '',            'string',  {}, [],       {}, {'n/a'}, 'Optional UTF-8 TSV with index and name columns for atlas_file. Indices are actual voxel values, without offsets. Empty generates Region_<index> names. Requires atlas_file.')
e('preprocessing.atlas_type',           'jhu',         'string',  {'jhu','harvardoxford','jhu-tract'}, [], {}, {'n/a'}, 'Atlas used for parcellation.')
e('preprocessing.bundle_roi_dir',       '',            'string',  {}, [],       {}, {'n/a'}, 'Optional directory of bundle masks to use as the parcellation INSTEAD of the atlas, e.g. data/ismrm2015/scoring_data_Renauld2023/ROI. Must contain all_masks/ (containment corridors, which become the labels) and may contain endpoints/ and any_masks/ (gates, addressable by name but not labels). The atlas parcellation is preserved as parcellation_mask_<atlas_type> rather than discarded. Empty = atlas only. Set this when ROIs should be addressed by the names a scorer uses: an atlas label and a bundle of the same name are not the same region.')
e('preprocessing.t1_available',         false,         'logical', {}, [],       {}, {'n/a'}, 'A T1 volume is present alongside the DWI.')
e('preprocessing.use_t1_registration',  false,         'logical', {}, [],       {}, {'n/a'}, 'Register T1 to DWI space.')
e('preprocessing.register_to_mni',      false,         'logical', {}, [],       {}, {'n/a'}, 'Register to MNI space.')
e('preprocessing.dwell_time',           0.00058,       'numeric', {}, [1e-5 0.01], {}, {'n/a'}, 'Field-map (FUGUE) correction: effective echo spacing in SECONDS (time between phase-encode lines). Set it from the acquisition; the default is a generic guess. Displacement in voxels = field[Hz] x dwell_time x phase-encode lines, so a wrong value scales the correction. ISMRM 2015: 0.001.')
e('preprocessing.phase_encoding_dir',   'y',           'string',  {'x','x-','y','y-','z','z-'}, [], {}, {'n/a'}, 'Field-map (FUGUE) correction: phase-encoding axis and polarity (FUGUE --unwarpdir). ISMRM 2015: y (checked against GT: y- makes the distortion worse).')
e('preprocessing.fieldmap_units',       'auto',        'string',  {'auto','Hz','rad/s'}, [], {}, {'n/a'}, 'Units of the field map file. auto = from the file name (fmap_Hz / RadPerSec). Hz maps are converted to rad/s, which is what FUGUE expects.')

% ------------------------------------------------------------------ tractography
e('tractography.algorithm',             'hinec',       'string',  {'hinec','standard','mmf','template','stitching'}, [], {}, {'all'}, 'Tracking algorithm. hinec = interpolated streamlines (RK); mmf = moving frames tractography (advanceFrame: the frame is transported by the connection of the data, exponential step; docs/MMF_TRACTOGRAPHY.md); standard = FACT; stitching = short tractlets; template = the minimal worked example of the tracker interface (docs/TRACKER_INTERFACE.md).')
e('tractography.field',                 'dti',         'string',  {'dti','csd','lift'}, [],  {}, {'hinec','mmf','stitching'}, 'Direction source. dti = DTI principal eigenvector; csd = CSD FOD peaks (hinec and stitching); lift = the lifts of the bundles on M = Omega x RP^2 built from the raw signal (nim_lift_field), one frame and one connection 1-form per bundle where bundles cross (with mmf this is MMF-ml, multilayer moving frames, run by nim_tractography_mmf_ml; see docs/MMF_ML.md and tractography.lift); with hinec the lifts are a peak field, the lift nearest the incoming tangent at every stencil voxel as for csd.')
e('tractography.act',                   false,         'logical', {}, [],       {'act_enabled'}, {'hinec'}, 'Anatomically constrained tracking using WM/GM/CSF masks.')

% --- integrator -------------------------------------------------------------
e('tractography.integrator.method',     'rk4',         'string',  {'euler','rk2','rk4','rkf45'}, [], {'integrator'}, {'hinec','mmf','stitching'}, 'Numerical stepping scheme. NOTE: this is a method NAME, not an order claim. rkf45 here is Dormand-Prince: it advances on the 5th-order solution and uses the embedded 4th-order one only to size the next step. For mmf: euler, rk2, rk4 select the Lie group integrator of order 1, 2, 4 (Lie-Euler, exponential midpoint, CF4) around the exponential step; rkf45 is rejected (no embedded error estimate exists for it).')
e('tractography.integrator.step',       0.2,           'numeric', {}, [1e-6 10], {'step_size'}, {'all'}, 'Integration step in voxels. Fixed step, or the initial step for rkf45.')
e('tractography.integrator.tolerance',  0.01,          'numeric', {}, [1e-12 1], {'rkf_tolerance','rkf_tol'}, {'hinec'}, 'Adaptive error tolerance in voxels. rkf45 ONLY.')
e('tractography.integrator.step_min',   0.01,          'numeric', {}, [1e-9 10], {'step_min'}, {'hinec'}, 'Minimum adaptive step. rkf45 ONLY.')
e('tractography.integrator.step_max',   1.0,           'numeric', {}, [1e-6 10], {'step_max'}, {'hinec'}, 'Maximum adaptive step. rkf45 ONLY.')
e('tractography.integrator.safety',     0.9,           'numeric', {}, [0.01 1],  {'rkf_safety'}, {'hinec'}, 'Adaptive step safety factor. rkf45 ONLY.')
e('tractography.integrator.adaptive',   true,          'logical', {}, [],        {'adaptive_step'}, {'hinec'}, 'Adaptive step-size control. rkf45 ONLY. rkf45 with adaptive:false is fixed-step RKF45 (a real third mode, kept for completeness).')

% --- interpolation ----------------------------------------------------------
e('tractography.interpolation.method',  'trilinear',   'string',  {'trilinear','cubic','spline'}, [], {'interp_method'}, {'hinec','mmf','stitching'}, 'Spatial interpolation kernel for the direction field. These differ in SMOOTHNESS, which caps how much of an integrator formal order is reachable: a Runge-Kutta method of order p needs a right-hand side with p continuous derivatives. trilinear is C0 (kinked at every voxel face), cubic is C1 (Keys cubic convolution, NOT a spline - its second derivative jumps), spline is C2 (a genuine cubic spline). Measured here: RK4 reaches observed order 2.00 on trilinear, 3.06 on cubic and 4.00 on spline - one order per continuous derivative, on an unchanged tableau.')
e('tractography.interpolation.upsample',  1,           'numeric', {}, [0.05 8],  {}, {'hinec','mmf'}, 'Spatial sampling factor for the direction field: the field is sampled on a grid of spacing 1/upsample voxels before the interpolants are built. 1 = the acquisition grid. Above 1 refines toward the continuous field the samples imply; BELOW 1 coarsens, discarding spatial information, which is how the space axis of a convergence study is swept. The coordinate frame is unchanged, so positions, step sizes and lengths stay in native voxel units and runs at different factors are directly comparable. Note the u -> infinity limit is the native-resolution interpolant, not ground-truth anatomy.')

% --- seeding ----------------------------------------------------------------
e('tractography.seeding.density',       8,             'numeric', {}, [1 1000],  {'seed_density'}, {'all'}, 'Seeds per seeded voxel - honoured exactly. Placed on a deterministic sub-voxel lattice (perfect cubes) or a spread subset of one (other counts), so runs are reproducible.')
e('tractography.seeding.strategy',      'uniform',     'string',  {'uniform','random'}, [], {'seed_strategy'}, {'all'}, 'Seed placement. uniform = deterministic lattice (reproducible); random = jittered.')
e('tractography.seeding.fa_min',        0.05,          'numeric', {}, [0 1],     {'seed_fa_threshold'}, {'all'}, 'Minimum FA for a voxel to be seeded. Default 0.05 excludes CSF only.')
e('tractography.seeding.cl_min',        0,             'numeric', {}, [0 1],     {}, {'all'}, 'Minimum linear shape CL = (lambda_1 - lambda_2)/lambda_1 of the voxel tensor for a voxel to be seeded (nim_seed_cl_mask). 0 = off. A crossing fitted as one tensor has CL near 0, so e.g. 0.15 (the mmf.hold_min of the hold presets) keeps seeds out of crossings.')
e('tractography.seeding.coherence_min', 0,          'numeric', {}, [0 1],     {}, {'all'}, 'Minimum coherence of the principal direction for a voxel to be seeded (nim_seed_coherence_mask): the largest eigenvalue of the mean dyadic v1*v1'' over the 3 x 3 x 3 block, in [1/3, 1] (1 = all neighbours point the same way). 0 = off.')
e('tractography.seeding.roi',           {},            'list',    {}, [],        {}, {'all'}, 'Restrict seeding to these atlas regions. JHU indices and/or names, freely mixed. Empty = whole brain mask.')
e('tractography.seeding.roi_dilate',    0,             'numeric', {}, [0 10],    {}, {'all'}, 'Dilate the seed ROI by this many voxels before seeding.')

% --- termination ------------------------------------------------------------
e('tractography.termination.fa_min',    0.10,          'numeric', {}, [0 1],     {'termination_fa'}, {'all'}, 'Stop tracking below this FA. (NOT the legacy fa_threshold - see nim_config_retired.)')
e('tractography.termination.fa_mode',   'absolute',    'string',  {'absolute','percentile'}, [], {}, {'all'}, 'How the FA stop threshold is set. absolute = stop below termination.fa_min (unchanged behaviour). percentile = stop below the termination.fa_percentile-th percentile of THIS scan''s FA inside its brain mask, resolved per scan in runTractography before any tracker runs; fa_min is then ignored. Removes scanner-level FA offsets (the same absolute FA cuts different fractions of the brain on different scanners). The resolved value is logged and kept in options.termination_fa, with the configured one in options.termination_fa_config.')
e('tractography.termination.fa_percentile', 26.3,       'numeric', {}, [0 100],   {}, {'all'}, 'Percentile of the scan''s in-mask FA used as the stop threshold when fa_mode = percentile. Default 26.3 = the median percentile rank of FA 0.10 over the 76 ds000206 scans (the reference protocol), so it keeps the meaning of fa_min = 0.10.')
e('tractography.termination.angle_max', 225,           'numeric', {}, [0 3600],  {}, {'all'}, 'Maximum turn in DEGREES PER VOXEL OF ARC, i.e. a minimum radius of curvature R = 57.3/angle_max voxels. The default 225 is the classic 45 deg/step evaluated at the default step of 0.2. Step-invariant: the limit for one step is angle_max x the NOMINAL step arc (never the realised chord - that would make the limit method-dependent), so refining the step does not loosen the constraint. CEILING: tangents are sign-aligned because v1 is a line field, so a measured turn never exceeds 90 deg - any angle_max above 90/step is INERT, not merely loose, and 225 goes inert for any step >= 0.4. 0 disables the criterion outright, which is what a control run should use.')
e('tractography.termination.max_arc',   400,           'numeric', {}, [1 100000],{}, {'all'}, 'Maximum track arc length in voxels. Step-invariant: max_steps is derived as ceil(max_arc/step).')
e('tractography.termination.min_arc',   15,            'numeric', {}, [0 100000],{'min_length'}, {'all'}, 'Discard tracks shorter than this arc length in voxels.')

% --- filter -----------------------------------------------------------------
e('tractography.filter.include_roi',    {},            'list',    {}, [],        {}, {'all'}, 'Keep only tracks touching these regions (waypoint).')
e('tractography.filter.exclude_roi',    {},            'list',    {}, [],        {}, {'all'}, 'Discard tracks touching these regions.')
e('tractography.filter.mode',           'all',         'string',  {'all','any'}, [], {}, {'all'}, 'Whether a track must touch ALL include regions or ANY of them.')
e('tractography.filter.roi_dilate',     0,             'numeric', {}, [0 10],    {}, {'all'}, 'Dilate the include/exclude masks by this many voxels before testing.')
e('tractography.filter.endpoints_in',   {},            'list',    {}, [],        {}, {'all'}, 'Two regions; keep a track only if one END lands in the first and the other END in the second, either way round. This is an ENDPOINT test, not a waypoint test - include_roi asks whether a track passes through a region, this asks where it stops. It is half of how the ISMRM 2015 scorer defines a bundle (head + tail).')
e('tractography.filter.contained_in',   {},            'list',    {}, [],        {}, {'all'}, 'Keep a track only if EVERY point lies inside these regions. The other half of the ISMRM bundle definition (all_mask): a streamline that wanders outside the corridor is not that bundle, however it ends. Tracks are kept or dropped whole, never cut. Like every filter.* key this is a SELECTION: tracks.mat still holds the full tractogram (what gets scored) and the selection is saved beside it as roi_selection.mat with the per-criterion drop counts.')
e('tractography.filter.any_in',         {},            'list',    {}, [],        {}, {'all'}, 'Keep a track only if it touches these regions in AT LEAST ONE point (the scorer''s any_mask). Weaker than include_roi with mode all: one region, one point.')
e('tractography.filter.length',         {},            'list',    {}, [],        {}, {'all'}, 'Keep tracks whose total length in MILLIMETRES is within [min max]. Millimetres, not voxels - the scorer measures in RAS mm.')
e('tractography.filter.length_x',       {},            'list',    {}, [],        {}, {'all'}, 'Keep tracks whose NET displacement along x is within [min max] mm. Net: a track that doubles back cancels itself out.')
e('tractography.filter.length_y',       {},            'list',    {}, [],        {}, {'all'}, 'Keep tracks whose NET displacement along y is within [min max] mm.')
e('tractography.filter.length_z',       {},            'list',    {}, [],        {}, {'all'}, 'Keep tracks whose NET displacement along z is within [min max] mm.')
e('tractography.filter.length_x_abs',   {},            'list',    {}, [],        {}, {'all'}, 'Keep tracks whose TOTAL travel along x is within [min max] mm. Total: a track that doubles back adds to it.')
e('tractography.filter.length_y_abs',   {},            'list',    {}, [],        {}, {'all'}, 'Keep tracks whose TOTAL travel along y is within [min max] mm.')
e('tractography.filter.length_z_abs',   {},            'list',    {}, [],        {}, {'all'}, 'Keep tracks whose TOTAL travel along z is within [min max] mm.')
e('tractography.debug.trace',           false,         'logical', {}, [],        {}, {'hinec','mmf'}, 'Record a PER-STEP trace of the tracker: position, direction used, interpolated FA, turn angle, nominal vs realised step arc, sign flips, and termination reason. None of this survives to the saved polyline, which output.arc_step decimates, so it cannot be reconstructed afterwards. Off by default; see nim_track_diagnose. The mmf tracker writes the same record fields (pos, dir, fa, h, chord, turn, flip, n_steps, termination; flip is always false there, the gauge absorbs sign flips) plus drift, reanchored, kappa, s, coasted and confidence, so nim_track_diagnose reads both.')
e('tractography.debug.trace_max',       200,           'numeric', {}, [0 100000], {}, {'hinec','mmf'}, 'How many seeds to trace, sampled EVENLY across the seed list (a prefix would be one corner of the volume). 0 traces every seed, which is large: allow roughly max_steps x 12 doubles per seed per direction.')

% --- output -----------------------------------------------------------------
e('tractography.output.arc_step',       0,             'numeric', {}, [0 100],   {}, {'all'}, 'Resample saved streamlines to this arc-length spacing in voxels. 0 = store every integration step. Decouples file size from step size; integration accuracy is unaffected.')

% --- csd (field: csd only) --------------------------------------------------
e('tractography.csd.peaks_file',        '',            'string',  {}, [],        {'csd_peaks_file'}, {'hinec','stitching'}, 'Optional MAT file with peaks [X Y Z P 3], npeaks [X Y Z], and peak_w [X Y Z P] in dataset voxel-axis coordinates. When set, use this deterministic field instead of fitting native CSD. The file must match the dataset grid; no GT or scoring data is needed.')
e('tractography.csd.lmax',              4,             'numeric', {}, [2 16],    {'csd_lmax'}, {'hinec','stitching'}, 'Spherical harmonic order for CSD. Default 4, set from the data rather than convention: with the 32 directions of this acquisition lmax=6 needs 28 coefficients from 32 measurements and the response falls to r_4 = -0.035 against r_0 = 2.73, so deconvolution divides by a near-zero and amplifies noise - its primary FOD peak misses the tensor v1 by 26.6 deg in UNAMBIGUOUS single-fibre voxels, against 6.6 deg at lmax=4. lmax=2 spans exactly the tensor and cannot represent a crossing at all.')
e('tractography.csd.max_peaks',         3,             'numeric', {}, [1 10],    {'csd_max_peaks'}, {'hinec','stitching'}, 'Maximum FOD peaks retained per voxel.')
e('tractography.csd.peak_thresh',       0.2,           'numeric', {}, [0 1],     {'csd_peak_thresh'}, {'hinec','stitching'}, 'Minimum FOD peak amplitude as a fraction of the voxel maximum. The old default of 0.5 required a second fibre population to be at least half as strong as the first, which discards ordinary unequal crossings; MRtrix uses 0.1 for the equivalent. Peaks must now also be local maxima of the FOD, so a lower threshold admits genuine fibres rather than points on the shoulder of the first peak.')
e('tractography.csd.peak_min_sep',      45,            'numeric', {}, [0 180],   {'csd_peak_min_sep'}, {'hinec','stitching'}, 'Minimum angular separation between FOD peaks (degrees).')
e('tractography.csd.n_iter',            50,            'numeric', {}, [1 1000],  {}, {'hinec','stitching'}, 'CSD deconvolution iterations.')

% --- lift (field: lift; construction: hinec and mmf, read: mmf) -------------------------------------
e('tractography.lift.smooth',           0,             'numeric', {}, [0 10],    {}, {'hinec','mmf'}, 'Half-width T (voxels) of the regularisation of the orientation density along the fibres: each direction n_j is smoothed along x + t n_j, t = -T..T, weights T + 1 - |t|; 0 = off (nim_lift_field). Default 0: the kernel runs along straight lines, so on a bend of curvature k it mixes directions up to k T apart and pulls the lobe toward the upstream direction (ISMRM cingulum, k ~ 0.5 per voxel: the lifted curvature fell to 0.02 at T = 2). ISMRM mmf lift+hold F1 0.509 / 0.521 / 0.537 at T = 2 / 1 / 0.')
e('tractography.lift.smooth_kernel',    'straight',    'string',  {'straight','curved'}, [], {}, {'hinec','mmf'}, 'Path of the regularisation along the fibres (lift.smooth > 0): straight = the line x + t n_j; curved = the best of the circular arcs leaving (x, n_j) with curvature lift.smooth_kappa in lift.smooth_normals normal directions (and the straight line), the density read at each arc point in the dictionary direction nearest the arc tangent (Duits and Franken, IJCV 92:231-264, 2011: smoothing on position x orientation follows curves, not lines).')
e('tractography.lift.smooth_kappa',     [0.15 0.3 0.5], 'numeric', {}, [0 2],    {}, {'hinec','mmf'}, 'Curvatures (per voxel) of the arcs of lift.smooth_kernel: curved, besides the straight line; the ISMRM cingulum bends at ~0.5 per voxel.')
e('tractography.lift.smooth_normals',   8,             'numeric', {}, [1 64],    {}, {'hinec','mmf'}, 'Number of normal directions m = cos(q) e2 + sin(q) e3, q = 2 pi i / smooth_normals, in which the arcs of lift.smooth_kernel: curved bend.')
e('tractography.lift.bridge',           2,             'numeric', {}, [0 5],     {}, {'hinec','mmf'}, 'Nodes a lift is continued through where its lobe is lost, when it continues beyond within 20 degrees (fibres do not end inside white matter); 0 = off.')
e('tractography.lift.rel',              0.1,           'numeric', {}, [0 1],     {}, {'hinec','mmf'}, 'A lift is a local maximum of p(x,.) of at least rel times the voxel maximum.')
e('tractography.lift.mass_min',         0.1,           'numeric', {}, [0 1],     {}, {'hinec','mmf'}, 'Minimum lobe mass of a lift: the share of the deconvolved fibre within 20 degrees of it, an estimate of its volume fraction.')
e('tractography.lift.max_lifts',        3,             'numeric', {}, [1 5],     {}, {'hinec','mmf'}, 'Maximum lifts per voxel.')
e('tractography.lift.sep',              15,            'numeric', {}, [1 90],    {}, {'hinec','mmf'}, 'Minimum angle (degrees) between two lifts of a voxel.')
e('tractography.lift.ndirs',            300,           'numeric', {}, [50 2000], {}, {'hinec','mmf'}, 'Dictionary directions on the half sphere for the non-negative deconvolution.')
e('tractography.lift.kappa',            20,            'numeric', {}, [1 200],   {}, {'hinec','mmf'}, 'Concentration of the Watson kernel W(t) = exp(kappa (t^2 - 1)) of the orientation density p = sum_j a_j W(u.n_j).')
e('tractography.lift.ref_fa_pct',       90,            'numeric', {}, [50 99.9], {}, {'hinec','mmf'}, 'The single-fibre kernel is the median DTI l1 and (l2 + l3)/2 of the voxels above this FA percentile of the tissue.')
e('tractography.lift.iso',              'auto',        'string',  {}, [],        {}, {'hinec','mmf'}, 'Isotropic compartments of the forward model, which carry no direction: auto = the hindered (l_perp) and the free water (3e-3 mm^2/s); none = sticks only (false lifts where the tissue is isotropic).')
e('tractography.lift.continuation',     0,             'numeric', {}, [0 0.99],  {}, {'hinec','mmf'}, 'Continuation prior beta (nim_lift_field): a second deconvolution whose prior of few lifts weighs direction n_j by c_j = 1 - beta max W(n_j . u^), u^ the moving-frame continuation of each neighbouring lift to the voxel (its nodal connection, curvature included); the directions a neighbouring fibre continues into cost less. 0 = off; needs lift.sparsity > 0.')
e('tractography.lift.sparsity',         0.1,           'numeric', {}, [0 100],   {}, {'hinec','mmf'}, 'Prior of few lifts: the deconvolution minimises ||K a + K_iso c - y||^2 + sparsity (sum_j a_j)^2, so broad or isotropic signal goes to the isotropic compartments instead of becoming false lifts. ISMRM 2015 slab (32 directions): 0.1 keeps one lift in 85% of the single-bundle voxels at the v1 error (7.3 vs 7.5 deg) and halves the error in two-bundle crossings (12.8 vs 24.9 deg); 0 = none.')
e('tractography.lift.read_min',         0.25,          'numeric', {}, [0.01 1],  {}, {'mmf'}, 'The tracker reads a lift at a point when the corners carrying a lift within 30 degrees of the heading hold at least this share of the trilinear weight (renormalised over them). Inside crossings the weaker lift is missing at scattered nodes; at 0.5 31.9% of ISMRM 2015 half-tracks stopped there with 0.25-0.5 of the weight still on their lift.')
e('tractography.lift.interp',           'corner',      'string',  {'corner','sheet_linear','sheet_cubic'}, [], {}, {'mmf'}, 'How the lifted field is read at a point (nim_lift_connection): corner = at each of the 8 corners the lift nearest the heading, trilinear (C0, jumps where a corner switches lift); sheet_linear / sheet_cubic = the local sheet of the heading on the 4 x 4 x 4 nodes (branch-matched from the nearest corner), interpolated trilinearly / with the Keys cubic kernel (C1, interpolation.method: cubic).')
e('tractography.lift.stencil',          'ls',          'string',  {'ls','fd4'}, [], {}, {'mmf'}, 'Derivative of each lift along its matched branch for the lifted nodal connection (nim_lift_connection): ls = least-squares slope over t = -2..2; fd4 = the stencil of the nodal connection of field: dti, (M_-2 - 8 M_-1 + 8 M_+1 - M_+2) / 12. On the ISMRM ground truth, bends with kappa > 0.15: ls reads 0.37-0.61 of the curvature, fd4 0.45-0.71.')
e('tractography.lift.read_tol',         30,            'numeric', {}, [5 60],    {}, {'mmf'}, 'Degrees: a node contributes its lift to the point the tracker reads only when that lift is within read_tol of the heading. With mmf.hold the share of the weight so read is the confidence: the tract coasts where it falls below mmf.hold_min.')
e('tractography.lift.fit',              false,         'logical', {}, [],        {}, {'hinec','mmf'}, 'Refit the stick model of each voxel from its lifts (Levenberg-Marquardt). Off: on synthetic crossings it undoes the regularisation along the fibres.')

% --- mmf (algorithm: mmf only) ----------------------------------------------
e('tractography.mmf.mode',              'adaptive',    'string',  {'transport','reanchor','adaptive'}, [], {}, {'mmf'}, 'How the carried frame relates to the data frame along the tract (advanceFrame ''Mode''). transport = carried by the connection only, the data enter through the curvature and the gauge; reanchor = replaced by the data frame after every step (the direction from the data, the curvature of the step from the transport: the closest relative of streamline tracking, with an arc instead of a chord); adaptive = transport, re-anchored only after a step at whose end the carried e1 has drifted from the data''s e1 by mmf.reanchor_tol or more.')
e('tractography.mmf.reanchor_tol',      1e-3,          'numeric', {}, [0 10],    {}, {'mmf'}, 'Drift tolerance of the adaptive mode, radians: the angle between the carried e1 and the data''s e1 (modulo sign) at the end of a step at or above which the frame is re-read from the data. 0 re-anchors after every step like mode reanchor; a value above pi never, like transport.')
e('tractography.mmf.gradient_delta',    1e-3,          'numeric', {}, [1e-6 0.5], {}, {'mmf'}, 'Central-difference step, in voxels, for the derivative of the interpolated principal axis from which the connection (curvature) components are formed.')
e('tractography.mmf.connection',        'nodal',       'string',  {'nodal','derivative'}, [], {}, {'mmf'}, 'How the connection 1-forms are obtained (MMFtractography_notes, Sec. 7). nodal = computed at the voxel nodes from the nodal frames and INTERPOLATED between them with interpolation.method (the scheme of the notes: Computeconnection + interpGLL); derivative = central difference (step gradient_delta) of the principal axis of the interpolated dyadic at every query point (the adapter of 2026-10-20, kept to reproduce its runs).')
e('tractography.mmf.max_turn',          0,             'numeric', {}, [0 10],    {}, {'mmf'}, 'advanceFrame ''MaxTurn'' in radians per step (the notes'' default is 0.5). 0 = derive it from termination.angle_max as before (min(angle_max*h, 90) degrees per step; pi when angle_max <= 0).')
e('tractography.mmf.hold',              'none',        'string',  {'none','hold','march'}, [], {}, {'mmf'}, 'How a tract crosses degenerate data, where the tensor is a crossing fitted as a pancake and its principal axis means nothing (see mmf.hold_min). none = it does not: the tract reads the data, follows the axis of the pancake or stops on angle_max. hold = MMF-4h: it coasts through the zone on the mean connection of its last trusted nodes (advanceFrame ''Confidence''), a circle when the twist is zero. march = MMF-4s: it coasts on the curvature and the fan-out of those nodes marched by the flatness law of the connection (''HoldCurvature'' ''march''), exact on circles, logarithmic spirals and rays, and turning the curvature by the torsion on a helix. The volume, the mask and the FA floor stay stops inside the zone. config/mmf_dti_hold.yml and config/mmf_dti_march.yml turn them on; docs/MMF_TRACTOGRAPHY.md has the scores against the ground truth of the ISMRM 2015 phantom.')
e('tractography.mmf.hold_min',          0.2,           'numeric', {}, [0 1],     {}, {'mmf'}, 'Confidence floor of mmf.hold (advanceFrame ''HoldMin''): a point is degenerate where the linear shape CL = (lambda_1 - lambda_2)/lambda_1 of the voxel tensors, interpolated linearly and eroded by mmf.hold_guard, is below this. For a single bundle of eigenvalues 1.7, 0.3, 0.3 (CL 0.82) 0.2 is an equal crossing of about 80 degrees and 0.4 of about 70, but CL also falls with the anisotropy of the data, so the floor belongs to the dataset: 0.15 and 0.2 were the best of the floors scored on the ISMRM 2015 phantom, and on tissue of lower anisotropy 0.2 can mark half of the voxels. The tracker reports the share of the tissue voxels below the floor, before the erosion (meta.mmf.zone_fraction), and warns above 40 percent (mmf:holdZone): lower the floor there.')
e('tractography.mmf.hold_k',            3,             'numeric', {}, [1 100],   {}, {'mmf'}, 'Trusted nodes in the running mean the coast starts from (advanceFrame ''HoldK''), a positive integer.')
e('tractography.mmf.hold_guard',        0.5,           'numeric', {}, [0 5],     {}, {'mmf'}, 'Erosion radius of the confidence, voxels: its minimum over the point and 14 points at this distance, which keeps the last trusted nodes, whose connection the coast starts from, off the voxels next to the zone. CL is interpolated over the voxels of tissue alone and the minimum reads nothing else, so that neither the edge of the mask nor the FA floor is a zone. A larger guard is a longer coast.')
e('tractography.mmf.coast_max',         12,            'numeric', {}, [0 1000],  {}, {'mmf'}, 'Longest coast, voxels of arc (advanceFrame ''CoastMax'' = coast_max/step steps): a tract still in the zone after this stops with reason coast.')
e('tractography.mmf.exit_tol',          0.5,           'numeric', {}, [0 10],    {}, {'mmf'}, 'Largest angle, radians, between the carried e1 and the data''s e1 with which a tract may leave the zone (advanceFrame ''ExitTol''): it is re-anchored then, and above this the coast has left the bundle and the tract stops with reason exit (with reason angle if the data at the end of the step are further from the heading at its start than angle_max allows). It must sit above the disagreement of neighbouring voxels, a quarter of which differ by more than 0.2 rad on real data, so it is not mmf.reanchor_tol; 0.5 rad is 29 degrees. Adaptive and reanchor modes only: in transport mode nothing is re-anchored or tested on leaving.')
e('tractography.mmf.exit_delay',        0,             'numeric', {}, [0 100],   {}, {'mmf'}, 'Arc of coast beyond the edge of the zone before the exit test, voxels (advanceFrame ''ExitDelay'' = exit_delay/step steps). 0 = test at the first trusted node. These steps neither count towards coast_max nor reset it, and the volume, the mask and the FA floor stop them.')
e('tractography.mmf.veto_arc',          0,             'numeric', {}, [0 100],   {}, {'mmf'}, 'History veto of mmf.hold, look-back in voxels of arc (advanceFrame_ml ''VetoK'' = round(veto_arc/step); a run with it goes to nim_tractography_mmf_ml); 0 = off. A trusted step whose end the data see more than mmf.veto_tol from the heading veto_arc back is not taken: the tract returns there and coasts on its ring (a crossing whose tensor looks linear along the other bundle).')
e('tractography.mmf.veto_tol',          0.5236,        'numeric', {}, [0 1.5708], {}, {'mmf'}, 'History veto: largest angle, radians, between the data e1 at a step end and the heading mmf.veto_arc back (advanceFrame_ml ''VetoTol''; 0.5236 = 30 deg).')

% --- short tractlets and endpoint graph -------------------------------------
e('tractography.stitching.fragment_arc', 3, 'numeric', {}, [0.1 100], {}, {'stitching'}, 'Total bidirectional fragment arc in voxels; 3 is 6 mm at 2 mm resolution.')
e('tractography.stitching.min_fragment_arc', 1, 'numeric', {}, [0 100], {}, {'stitching'}, 'Discard local fragments shorter than this voxel arc before graph assembly.')
e('tractography.stitching.join', true, 'logical', {}, [], {}, {'stitching'}, 'Enable endpoint stitching. False is the fragment-only ablation.')
e('tractography.stitching.join_radius', 1, 'numeric', {}, [0.01 10], {}, {'stitching'}, 'Maximum endpoint gap in voxels.')
e('tractography.stitching.join_angle', 30, 'numeric', {}, [0 89], {}, {'stitching'}, 'Maximum endpoint tangent and forward-gap alignment angle, degrees.')
e('tractography.stitching.bridge_angle', 45, 'numeric', {}, [0 89], {}, {'stitching'}, 'Maximum bridge tangent disagreement with the local field, degrees.')
e('tractography.stitching.search', 'knn', 'string', {'knn','forward'}, [], {}, {'stitching'}, 'Endpoint search: knn caps before compatibility; forward searches the full forward cone and caps compatible candidates across distance/direction sectors.')
e('tractography.stitching.neighbors', 16, 'numeric', {}, [1 128], {}, {'stitching'}, 'Endpoint candidate limit: raw nearest endpoints for knn; compatible sector-balanced endpoints for forward.')
e('tractography.stitching.curvature_tolerance', 0.25, 'numeric', {}, [0.001 10], {}, {'stitching'}, 'Maximum endpoint curvature difference, inverse voxels, applied by the endpoint graph when a per-endpoint curvature/torsion table is supplied to nim_stitch_fragments (the pipeline currently supplies none).')
e('tractography.stitching.torsion_tolerance', 0.5, 'numeric', {}, [0.001 10], {}, {'stitching'}, 'Maximum endpoint torsion difference when curvature is nonzero, inverse voxels; same condition as curvature_tolerance.')
e('tractography.stitching.max_fragments', 200000, 'numeric', {}, [1 10000000], {}, {'stitching'}, 'Fail before generation if seed count times possible peaks exceeds this explicit memory limit.')

% --- diagnostics ------------------------------------------------------------
e('tractography.diagnostics',           true,          'logical', {}, [],        {'enable_diagnostics'}, {'all'}, 'Write per-run diagnostic reports.')
];

end
